import * as React from "react";
import { cx } from "./cx";
import { DropdownMenu, type DropdownMenuItem } from "./dropdown-menu";

export interface MenubarProps extends React.HTMLAttributes<HTMLDivElement> {
  menus: Array<{ label: React.ReactNode; items: DropdownMenuItem[] }>;
}

/** Dropdown menus in a hairline strip. */
export function Menubar({ menus, className, ...props }: MenubarProps) {
  return (
    <div role="menubar" className={cx("rs-menubar", className)} {...props}>
      {menus.map((menu, index) => (
        <DropdownMenu key={index} label={menu.label} items={menu.items} />
      ))}
    </div>
  );
}

import * as React from "react";
import { cx } from "./cx";
import { Icon } from "./icon";

export interface DropdownMenuItem {
  label?: React.ReactNode;
  onSelect?: () => void;
  disabled?: boolean;
  separator?: boolean;
}

export interface DropdownMenuProps extends React.HTMLAttributes<HTMLDivElement> {
  label: React.ReactNode;
  items: DropdownMenuItem[];
}

/** Action menu with menu semantics and keyboard navigation. */
export function DropdownMenu({ label, items, className, ...props }: DropdownMenuProps) {
  const idBase = React.useId();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const [open, setOpen] = React.useState(false);
  const actionable = items.filter((item) => !item.separator);
  const [activeIndex, setActiveIndex] = React.useState(0);

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  const select = (item: DropdownMenuItem) => {
    if (item.disabled) return;
    setOpen(false);
    triggerRef.current?.focus();
    item.onSelect?.();
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!open) {
      if (["ArrowDown", "ArrowUp", "Enter", " "].includes(e.key)) {
        e.preventDefault();
        setActiveIndex(0);
        setOpen(true);
      }
      return;
    }
    if (e.key === "Escape") {
      setOpen(false);
      triggerRef.current?.focus();
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(actionable.length - 1, i + 1));
    }
    if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(0, i - 1));
    }
    if (e.key === "Home") setActiveIndex(0);
    if (e.key === "End") setActiveIndex(actionable.length - 1);
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      const item = actionable[activeIndex];
      if (item) select(item);
    }
  };

  let actionIndex = -1;
  return (
    <div ref={rootRef} className={cx("rs-select", className)} onKeyDown={onKeyDown} {...props}>
      <button
        ref={triggerRef}
        type="button"
        className="rs-dropdown"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={`${idBase}-menu`}
        onClick={() => setOpen((o) => !o)}
      >
        <span>{label}</span>
        <Icon name="chevron-right" rotate={90} />
      </button>
      {open && (
        <div id={`${idBase}-menu`} role="menu" className="rs-menu">
          {items.map((item, index) => {
            if (item.separator) return <hr key={`sep-${index}`} className="rs-menu-sep" />;
            actionIndex++;
            const current = actionIndex;
            return (
              <button
                key={index}
                type="button"
                role="menuitem"
                disabled={item.disabled}
                className={cx("rs-menu-item", current === activeIndex && "rs-menu-item-active")}
                onPointerEnter={() => setActiveIndex(current)}
                onClick={() => select(item)}
              >
                {item.label}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

import * as React from "react";
import { cx } from "./cx";

/**
 * Raster chrome marks. Vera 28 Aug 2026.
 *
 * 16×16 module, optical center 8,8. Stroke 1, currentColor, fill none.
 * Cap butt, join miter, no rx. Hairline stays 1 CSS px at 12 and 16.
 * Copied is check. Accordion down is chevron-right rotated 90°.
 */
export const ICON_STROKE = 1;
export const ICON_VIEWBOX = 16;

export const iconInk = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: ICON_STROKE,
  strokeLinecap: "butt",
  strokeLinejoin: "miter",
  vectorEffect: "non-scaling-stroke",
} as const;

export const iconNames = ["copy", "copied", "chevron-left", "chevron-right", "close"] as const;
export type IconName = (typeof iconNames)[number] | "check";
export type IconSize = 12 | 16;
export type IconRotate = 90 | 180 | 270;

const marks: Record<(typeof iconNames)[number], React.ReactNode> = {
  copy: (
    <>
      <path d="M6.5 2.5 H13.5 V9.5" {...iconInk} />
      <rect x="2.5" y="6.5" width="7" height="7" {...iconInk} />
    </>
  ),
  copied: <path d="M3.5 8.5 L6.5 11.5 L12.5 4.5" {...iconInk} />,
  "chevron-left": <path d="M10.5 3.5 L5.5 8 L10.5 12.5" {...iconInk} />,
  "chevron-right": <path d="M5.5 3.5 L10.5 8 L5.5 12.5" {...iconInk} />,
  close: (
    <>
      <path d="M4.5 4.5 L11.5 11.5" {...iconInk} />
      <path d="M11.5 4.5 L4.5 11.5" {...iconInk} />
    </>
  ),
};

function resolveName(name: IconName): (typeof iconNames)[number] {
  return name === "check" ? "copied" : name;
}

export interface IconProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children" | "rotate"> {
  name: IconName;
  size?: IconSize;
  /** Same mark, spun around 8,8. Accordion down is chevron-right at 90. */
  rotate?: IconRotate;
}

/** One mark. Size is the drawn square; the viewBox is always 16. */
export function Icon({ name, size = 16, rotate, className, ...props }: IconProps) {
  const nodes = marks[resolveName(name)];
  return (
    <svg
      className={cx("rs-icon", className)}
      viewBox="0 0 16 16"
      width={size}
      height={size}
      aria-hidden="true"
      {...iconInk}
      {...props}
    >
      {rotate ? <g transform={`rotate(${rotate} 8 8)`}>{nodes}</g> : nodes}
    </svg>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

